def _mps_moe_supports_lora(device: torch.device | str | None = None) -> bool:
    """Mirror of ``_cuda_moe_supports_lora`` for MPS — gate routed multi-adapter
    MoE-LoRA support on the device being MPS and MPS being available."""
    if device is None:
        if not torch.backends.mps.is_available():
            return False
        device = torch.device("mps")
    else:
        device = torch.device(device)
    if device.type != "mps":
        return False
    return torch.backends.mps.is_available()


class MPSKernelRuntime(KernelRuntime):
    """PyTorch MPS backend.

    Properties return sub-runtimes populated with real torch-based implementations
    where available. See ``docs/MAC_SUPPORT.md`` for roadmap.
    """

    def _build_attention_runtime(self) -> AttentionRuntime:
        return AttentionRuntime(
            flash_attn_fwd=flash_attn_fwd_mps,
            block_bidirectional_mask=block_bidirectional_mask_mps,
            windowed_blockdiag_mask=windowed_blockdiag_mask_mps,
        )

    @property
    def moe(self) -> MoeRuntime:
        from kestrel_kernels.moe.dispatch import (
            forward as moe_forward,
            prepare as moe_prepare,
        )
        from kestrel_kernels.moe import prepare_lora_metadata

        return MoeRuntime(
            prepare=moe_prepare,
            forward=moe_forward,
            topk_fwd=mps_moe.topk_fwd_mps,
            prepare_lora_metadata=prepare_lora_metadata,
            supports_lora=_mps_moe_supports_lora,
        )

    @property
    def cache(self) -> CacheRuntime:
        return CacheRuntime(
            reshape_and_cache_flash=reshape_and_cache_flash_mps,
            build_paged_kv_metadata=build_paged_kv_metadata_mps,
        )

    @property
    def rotary(self) -> RotaryRuntime:
        return RotaryRuntime(
            rotary_embedding=rotary_embedding_mps,
            prepare_neox=prepare_neox_rotary,
            apply_neox=apply_neox_rotary,
            text_mrope_apply=text_mrope_apply_torch,
            spatial_rope_apply=spatial_rope_apply_torch,
        )

    @property
    def tau(self) -> TauRuntime:
        return TauRuntime(
            tau_tail_apply_into=tau_tail_apply_into_mps,
        )

    @property
    def vision(self) -> VisionRuntime:
        return VisionRuntime(
            fused_linear_bias_residual_into=fused_linear_bias_residual_into_mps,
        )

    @property
    def linear(self) -> LinearRuntime:
        return LinearRuntime(
            linear=linear_mps,
            block_scaled_linear=block_scaled_linear,
        )

    @property
    def gelu(self) -> GeluRuntime:
        return GeluRuntime(gelu_cute=gelu_cute_mps)

    @property
    def gated_delta(self) -> GatedDeltaRuntime:
        return GatedDeltaRuntime(
            allocate_packed_gated_delta_prefill_workspace=(
                allocate_packed_gated_delta_prefill_workspace
            ),
            bind_packed_prefill_topology=bind_packed_prefill_topology,
            causal_conv1d_packed=causal_conv1d_packed_mps,
            causal_conv1d_update_indexed=causal_conv1d_update_indexed_mps,
            gated_rmsnorm=gated_rmsnorm_mps,
            materialize_replay_state_indexed=materialize_replay_state_indexed_torch,
            packed_gated_delta_rule_prefill=packed_gated_delta_rule_prefill_mps,
            packed_prefill_prepare=packed_prefill_prepare_mps,
            packed_recurrent_gated_delta_rule_decode_replay_indexed=(
                packed_recurrent_gated_delta_rule_decode_replay_indexed_mps
            ),
            packed_recurrent_gated_delta_rule_decode_replay_indexed_gqa=(
                packed_recurrent_gated_delta_rule_decode_replay_indexed_torch
            ),
            packed_recurrent_gated_delta_rule_prefill=(
                packed_recurrent_gated_delta_rule_prefill_mps
            ),
            packed_recurrent_gated_delta_rule_verify_replay_indexed=(
                packed_recurrent_gated_delta_rule_verify_replay_indexed_torch
            ),
            supports_packed_gdn=supports_packed_gdn_mps,
        )

    @property
    def dense(self) -> DenseRuntime:
        return DenseRuntime(
            fused_mlp_gelu_bias_residual=fused_mlp_gelu_bias_residual_cuda_mps,
            mlp_gelu_bias_residual=mlp_gelu_bias_residual_mps,
            layernorm_bias_into=layernorm_bias_into_mps,
            layernorm_bias=layernorm_bias_mps,
            rmsnorm_into=rmsnorm_into_mps,
            rmsnorm=rmsnorm_mps,
            add_rmsnorm_into=add_rmsnorm_into_mps,
            add_rmsnorm=add_rmsnorm_mps,
            gated_activation_into=gated_activation_into_mps,
        )

    @property
    def sampling(self) -> SamplingRuntime:
        return SamplingRuntime(
            sample_step_from_logits=sample_step_from_logits_mps,
            greedy_logprobs_from_logits=greedy_logprobs_from_logits,
            apply_logits_constraints_=apply_logits_constraints_,
            constrained_argmax_from_logits=constrained_argmax_from_logits,
            greedy_tail_from_logits=greedy_tail_from_logits,
            allocate_greedy_tail_workspace=allocate_greedy_tail_workspace,
        )

    @property
    def compute_capability(self) -> tuple[int, int]:
        return (0, 0)

    @property
    def is_sm90(self) -> bool:
        return False


__all__ = ["MPSKernelRuntime"]
